(4,'小火龙',2500,'要是把它带到安静的地方，就能听到它的尾巴燃烧时发出的微小的声音。',875,'火','',39,52,43,60,50,65,'173',150,10,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
