(24,'阿柏怪',0,'根据研究证实，它腹部那可怕的纹路大约有６个种类已经得到确认。',500,'毒','',60,95,69,65,79,80,'152,153,157,182',45,40,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
