(173,'皮宝宝',5000,'据说是乘着流星而来。皮宝宝好像会出现在以前有陨石坠落过的地方。',250,'妖精','',50,25,28,45,55,15,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(174,'宝宝丁',5000,'如果不去管它，它就会一直练习唱歌。所以还是让它休息会，别伤到了嗓子。',250,'普通','妖精',90,30,15,40,20,15,'131',0,30,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(175,'波克比',5000,'能将人和宝可梦发出的温情和喜悦这些情感转化成能量。会将壳里储存的幸福分发出去。',875,'妖精','',35,20,65,40,65,20,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(176,'波克基古',5000,'据说是会带来幸运的宝可梦。如果发现心灵纯洁的人或宝可梦，就会现身并将幸福分给他们。',875,'妖精','飞行',55,40,85,80,105,40,'193',0,10,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(177,'天然雀',5000,'在啄食时能灵巧地避开仙人掌的花蕾和刺。跳来跳去地移动。',500,'超能','飞行',40,50,45,70,45,70,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(178,'天然鸟',0,'能够看穿过去和未来。日复一日注视着太阳动向的奇异宝可梦。',500,'超能','飞行',65,75,70,95,70,95,'180,184',90,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 1}',0,0,'[0, 0]',1),
(179,'咩利羊',5000,'绒毛摩擦产生的电力会被储存起来。如果觉得可爱而直接用手碰它的话，就会被啪地一下电得又麻又痛。',500,'电','',55,40,40,65,45,35,'180',70,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(180,'茸茸羊',0,'能将电力储存在松软的毛发中。因为储存了太多电力，所以身上有些地方已经变得光秃秃的了。',500,'电','',70,55,55,80,60,45,'109,112',120,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(181,'电龙',0,'尾巴会发出很强的亮光。从以前起，它就被船员们当做路标而深受重视。',500,'电','',90,75,85,115,90,55,'172',20,20,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 3, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(182,'美丽花',0,'进化前的臭臭花越臭，就越是能进化为带着美丽花儿的美丽花哦。到了晚上就会合上花瓣睡觉。',500,'草','',75,80,95,90,100,50,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,0,'[0, 0]',1),
(183,'玛力露',5000,'在水流湍急的河中捕食的时候，会用尾巴缠住岸边的树干。尾巴有弹性，有着可以伸长的构造。',500,'水','妖精',70,20,50,20,50,40,'107,120,128,143,148,149',35,20,1,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(184,'玛力露丽',0,'可以制造空气球。如果碰到溺水的宝可梦，就会把空气球拿出来给它，以便让它能够呼吸。',500,'水','妖精',100,50,80,60,80,50,'173',0,15,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(185,'树才怪',5000,'它之所以会有柔软又结实的手臂，是因为在长期摆出同样姿势的过程中得到了锻炼。',500,'岩石','',70,100,115,30,65,30,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',0),
(186,'蚊香蛙皇',0,'蚊香蛙皇头上的卷毛越长，长得越仪表堂堂，就越能领导更多的蚊香蝌蚪和蚊香君。',500,'水','',90,75,75,90,100,70,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,0,'[0, 0]',1),
(187,'毽子草',5000,'能随风轻轻飘浮的宝可梦。如果感到有强风要来的迹象，伙伴之间就会互相绑紧叶子，做好不被强风吹走的准备。',500,'草','飞行',35,35,40,35,55,50,'151',180,65,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(188,'毽子花',0,'气温超过１８度就会开花。开花方式会随温度的不同而变化，所以有时也会用它来代替温度计。',500,'草','飞行',55,45,50,45,65,80,'151',120,60,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(189,'毽子棉',0,'会乘着温暖的南风飞越大海，一直飞到外国的宝可梦。遇到冷空气就会降落到地面上。',500,'草','飞行',75,55,70,55,95,110,'151',60,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 3}',0,0,'[0, 0]',1),
(190,'长尾怪手',5000,'会从树上寻找猎物。发现喜食的甜竹竹后，就会兴奋地飞扑过去。',500,'普通','',55,70,55,40,55,85,'180',120,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(191,'向日种子',5000,'为了将体内储存的营养一直保留到进化那一刻，它几乎不会动一下。平时它什么都不吃只饮朝露。',500,'草','',30,30,30,30,30,30,'180',200,60,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(192,'向日花怪',0,'会从太阳的能量中制造出营养。在气温高的白天会频繁地活动，太阳下山后会突然变得一动不动。',500,'草','',75,75,55,105,85,30,'167,168',90,40,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(193,'蜻蜻蜓',5000,'不转动眼珠就可以３６０度环视。擅长急停和转向，很快便能将它盯上的猎物追得走投无路。',500,'虫','飞行',65,65,45,75,45,95,'149',120,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(194,'乌波',5000,'平时生活在水中，觅食等时候偶尔会来到地上。在陆地上会用有毒的粘液覆盖身体。',500,'水','地面',55,45,45,25,25,15,'180',190,50,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(195,'沼王',0,'会在水里张开嘴巴，然后就只是静静地等着食物自己碰巧跳进来。因为不会动，所以肚子也不怎么会饿。',500,'水','地面',95,85,85,65,65,35,'',0,0,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(196,'太阳伊布',0,'体毛有着天鹅绒般的光泽和手感。当它使用精神力量时，额头的珠子会放出光芒。',875,'超能','',65,65,60,130,95,110,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(197,'月亮伊布',0,'会潜伏在暗处袭击猎物。在发动袭击的瞬间，它身上的圈圈会发出黯淡的诡异之光。',875,'恶','',95,65,110,60,130,65,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(198,'黑暗鸦',5000,'会为老大去寻找闪闪发光的东西。据说它很不吉利，厌恶它的人也很多。',500,'恶','飞行',60,85,42,85,42,91,'113,179',80,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(199,'呆呆王',0,'被称为大海的贤者。虽然会去和智挥猩比拼智力，但结果多是不分上下。',500,'水','超能',95,75,80,100,110,30,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,0,'[0, 0]',1),
(200,'梦妖',5000,'深更半夜从背后接近，发出彷佛哭喊般的声音来吓唬人们，并以此为乐的宝可梦。',500,'幽灵','',60,60,60,85,85,85,'152',80,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(201,'未知图腾',0,'很像古代文明的文字。是先有文字还是先有未知图腾，这是世界七大不可思议之一。',-1,'超能','',48,72,48,72,48,48,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(202,'果然翁',5000,'它会拼命隐藏黑色的尾巴，人们认为这正是尾巴里藏有秘密的证据。',500,'超能','',190,33,58,33,58,33,'173',0,0,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(203,'麒麟奇',5000,'虽然尾巴上的脑袋小到无法思考，但因为不睡觉也没关系，所以会２４小时持续监视周围的情况。',500,'普通','超能',70,80,65,90,65,85,'180',45,60,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(204,'榛果球',5000,'会用唾液将树皮粘在自己身上，从而让自己变得又厚又大。上了年纪的榛果球是无比巨大的。',500,'虫','',50,65,90,35,35,15,'180',160,65,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(205,'佛烈托斯',0,'仅在吞下猎物的瞬间，壳里面的身体才会出现，但至今仍未有人或宝可梦见过其真面目。',500,'虫','钢',75,90,140,60,60,40,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(206,'土龙弟弟',5000,'一看到人就会用尾巴挖洞逃走。如果遇到了它，就说明你很幸运哦。',500,'普通','',100,70,70,65,65,45,'118',190,60,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(207,'天蝎',5000,'它会像在地上滑行时一样悄无声息地滑过天空。能用双臂上的大爪子和脚上的爪子抓住猎物的脸，然后再刺入毒针',500,'地面','飞行',65,75,105,35,65,85,'180',60,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(208,'大钢蛇',0,'人们认为它的身体是因为堆积了很多和泥土一起吞下的铁元素，才会发生变化的。',500,'钢','地面',75,85,200,55,65,30,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(209,'布鲁',5000,'它和看上去不同，其实很胆小。所以如果把它和小狗宝可梦放在一起，它就有可能会受到欺负。',250,'妖精','',60,80,50,40,40,30,'180',40,37,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(210,'布鲁皇',0,'虽然深受年轻女性的欢迎，但它胆小怕事，内心柔弱，所以无法成为一条看门犬。',250,'妖精','',90,120,75,60,60,45,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(211,'千针鱼',0,'吞下水后，会利用水的力量将全身的毒针一起发射出去。是不太擅长游动的宝可梦。',500,'水','毒',65,95,85,55,55,85,'110',0,30,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(212,'巨钳螳螂',0,'一旦将对方认定为敌人，就会用钢铁般坚硬的钳子持续殴打对方，直到其粉身碎骨。',500,'虫','钢',70,130,100,55,80,65,'168',20,10,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(213,'壶壶',5000,'会在岩石下面一边吃着甲壳里储存的树果一边隐藏身体。树果和体液混合后会变成果汁。',500,'虫','岩石',20,10,230,10,230,5,'191',0,5,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(214,'赫拉克罗斯',5000,'会在森林中四处寻找甜甜蜜。虽然对于自己的一身怪力很是自豪，但却不怎么擅长飞行。',500,'虫','格斗',80,125,75,40,95,85,'180',50,20,1,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(215,'狃拉',5000,'会趁着夜色袭击猎物。伸出爪子袭击穿山鼠时，有时会因对方坚硬的皮肤而导致爪子折断。',500,'恶','冰',55,95,55,35,75,115,'152,153',30,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(216,'熊宝宝',5000,'一直在舔渗入了蜂蜜的手掌。熊宝宝的蜂蜜是由水果和大针蜂收集的花粉混合后制成的。',500,'普通','',60,80,50,50,50,40,'180',30,40,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(217,'圈圈熊',0,'据说森林里到处都是圈圈熊用来收集食物的大树和小河。每天都会为了搜集食物在森林里走动。',500,'普通','',90,130,75,75,75,55,'184',50,30,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(218,'熔岩虫',5000,'代替了体内血液的灼热熔岩正在不断循环，为身体输送着必要的营养和氧气。',500,'火','',40,40,40,70,40,20,'123',200,75,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(219,'熔岩蜗牛',0,'据说体温约有１万度，因此被雨点打到后会蒸汽弥漫，身体周围会被浓厚的雾气所笼罩。',500,'火','岩石',60,50,120,90,80,30,'122,135',120,20,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(220,'小山猪',5000,'会用鼻子摩擦地面觅食。喜欢吃枯草下长出的蘑菇。偶尔也会挖到温泉哦。',500,'冰','地面',50,50,40,30,30,50,'181',150,50,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(221,'长毛猪',0,'朝着对手冲过去时，背上的体毛会倒竖起来。对声音极度敏感。',500,'冰','地面',100,100,80,60,60,50,'152,153',45,30,0,'{\"hp\": 1, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(222,'太阳珊瑚',5000,'头顶上长着珊瑚枝。虽然相当容易折断，但大约３天就能恢复哦。',250,'水','岩石',65,55,95,65,95,35,'165,178',40,20,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(223,'铁炮鱼',5000,'它又被称为海洋狙击手。即便是１００米开外的猎物，它射出的水枪也一定能够命中。',500,'水','',35,65,35,65,35,65,'180',60,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(224,'章鱼桶',0,'岩洞是它主要的栖身之所。章鱼桶吐出的漆黑墨汁还会被当成制作料理时的食材。',500,'水','',75,105,75,105,75,45,'168',70,30,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(225,'信使鸟',5000,'会用尾巴将食物裹起来运送。尾巴最大的信使鸟就是群体里的老大。',500,'冰','飞行',45,55,45,65,45,75,'181',30,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(226,'巨翅飞鱼',5000,'悠然地畅游在大海中。就算有觊觎食物残渣的铁炮鱼吸附在自己身上也毫不在意。',500,'水','飞行',85,40,70,80,140,70,'111',50,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(227,'盔甲鸟',5000,'由于它身上掉落下来的羽毛可以用来制剑，因此作为纹章的图案也很有人气。',500,'钢','飞行',65,80,140,40,70,70,'123',42,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(228,'戴鲁比',5000,'会在天亮之前反复发出恐怖的长嚎，并以此来彰显自己群体的存在。',500,'恶','火',45,60,30,80,50,65,'157,180',80,60,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(229,'黑鲁加',0,'恐怖的长嚎是其特征。过去人们曾认为它是来自地狱的使者而对其心存畏惧。',500,'恶','火',75,90,50,110,80,95,'157,184',0,10,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(230,'刺龙王',0,'沉睡在没有生物居住的海底。据说台风来到时就会醒来，四处徘徊寻找猎物。',500,'水','龙',75,95,95,95,95,85,'168',80,30,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(231,'小小象',5000,'会用长鼻子冲凉。伙伴们聚集起来后就会互相喷水。会在岸边晒干湿透的身体哦。',500,'地面','',90,60,60,40,40,40,'180',80,40,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(232,'顿甲',0,'就算是房屋都会被它那坚硬的身体撞毁。会用这种力量帮忙把山体滑坡中滚落下来阻塞山路的泥石移开哦。',500,'地面','',90,120,120,60,60,50,'180',30,30,0,'{\"hp\": 0, \"atk\": 1, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(233,'多边兽Ⅱ',0,'虽然在宇宙空间里也不会死亡，但在无重力的环境下，它无法顺利地转动身体。',-1,'普通','',85,80,90,105,95,60,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(234,'惊角鹿',5000,'由于形状完美的角作为艺术品可以卖出高价钱，因此该宝可梦曾遭滥捕差点灭绝。',500,'普通','',73,95,62,85,65,85,'180',20,50,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(235,'图图犬',5000,'会用尾巴前端渗出的体液画下标记。对于有些标记，爱好者会以高价买卖。',500,'普通','',55,20,35,20,45,75,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(236,'无畏小子',5000,'以性格冲动而闻名。就算对方比自己高大也会上前挑战，因此身上伤痕不断。',1000,'格斗','',35,35,35,35,35,35,'179',60,30,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(237,'战舞郎',5000,'会像陀螺一样旋转着战斗。由于离心力的作用，破坏力可达到原来的１０倍。',1000,'格斗','',50,95,95,35,110,70,'168',100,30,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(238,'迷唇娃',5000,'嘴唇是敏感的感应器。为了不让嘴唇干裂，它每天都会用树汁涂抹嘴唇来保湿哦。',0,'冰','超能',45,30,15,85,65,65,'',0,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(239,'电击怪',5000,'当角发出青白色亮光时，就表示充电已经完成了。如果去摸，就会被电得麻麻的。',750,'电','',45,63,37,65,55,95,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(240,'鸭嘴宝宝',5000,'体温经常在６００度左右。如果鸭嘴宝宝掉到池塘里，池塘里的水就会被蒸发干净。',750,'火','',45,75,37,70,55,83,'122',60,10,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(241,'大奶罐',5000,'牛奶很可口又富含营养。但要小心，如果喝多了，有时就会拉肚子。',0,'普通','',95,80,105,40,70,100,'180',50,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(242,'幸福蛋',0,'心中充满着爱的宝可梦。据说只有和训练家心灵相通的吉利蛋才能进化。',0,'普通','',255,10,10,75,135,55,'',0,0,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(243,'雷公',0,'体内蕴藏着雷电般速度的宝可梦。它的长嚎会如同天雷落地时一样震动空气，摇撼大地。',-1,'电','',90,85,75,115,100,115,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 2}',0,1,'[0, 0]',1),
(244,'炎帝',0,'体内蕴藏着熔岩般热情的宝可梦。被认为是从火山的喷发中诞生，能喷出燃尽一切的火焰。',-1,'火','',115,115,85,90,75,100,'',0,0,0,'{\"hp\": 1, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,1,'[0, 0]',1),
(245,'水君',0,'体内蕴藏着泉水般温柔的宝可梦。会用滑行一样的动作在大地上奔跑，有着净化浑水的力量。',-1,'水','',100,75,115,90,115,85,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,1,'[0, 0]',1),
(246,'幼基拉斯',10000,'靠着土壤中的养分长大。当吃下大约一座山那么多的土后，它就会变成蛹。',500,'岩石','地面',50,64,50,45,50,41,'',0,0,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(247,'沙基拉斯',0,'会到处胡闹，相当危险的蛹。在岩盘一样的外壳内，新的身体正在逐渐成形。',500,'岩石','地面',70,84,70,65,70,51,'0',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(248,'班基拉斯',0,'在前进的道路上，它会遇山毁山，遇楼拆楼，是一种会移动的灾害型宝可梦。',500,'岩石','恶',100,134,110,95,100,61,'',0,50,0,'{\"hp\": 0, \"atk\": 3, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(249,'洛奇亚',0,'沉睡在很深的海沟底部。据说洛奇亚挥动翅膀的话，就会引起长达４０天的暴风雨。',-1,'超能','飞行',106,90,130,90,154,110,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,1,'[0, 0]',1),
(250,'凤王',0,'据说在不同角度光线的照射下，会闪耀七彩光芒的羽毛能带来幸福。据传它住在彩虹的脚下。',-1,'火','飞行',106,130,90,110,154,90,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,1,'[0, 0]',1),
(251,'时拉比',0,'能够使用穿越时光的力量。据说只会出现在和平的时代。',-1,'超能','草',100,100,100,100,100,100,'',0,0,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,1,'[0, 0]',1),
(252,'木守宫',2500,'沉着冷静，对任何事都能镇定自若。就算被体型很大的宝可梦瞪住，也会毫不退让地瞪回去。',875,'草','',40,45,35,65,55,70,'',30,10,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(253,'森林蜥蜴',0,'能在枝头间轻巧地跳来跳去。不管是多快的宝可梦，都无法在森林中捉住森林蜥蜴。',875,'草','',50,65,45,85,65,95,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(254,'蜥蜴王',0,'据说背上的种子里贮存了许多能让树木生机盎然的营养。是会小心培育森林里树木的宝可梦。',875,'草','',70,85,65,105,85,120,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 3}',0,0,'[0, 0]',1),
(255,'火稚鸡',2500,'体内有着让火焰燃烧的地方，因此抱在怀里暖烘烘的非常温暖。全身覆盖着蓬松的羽毛。',875,'火','',45,60,40,70,50,45,'',100,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(256,'力壮鸡',0,'会用鸟嘴里吐出的灼热火焰和极具破坏力的腿技战斗。因为叫声很大，所以非常吵。',875,'火','格斗',60,85,60,85,60,55,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(257,'火焰鸡',0,'有着强韧的腰腿，连３０层大楼都能轻松跃过。会用火焰拳把对手烧焦。',875,'火','格斗',80,120,70,110,70,80,'',0,0,0,'{\"hp\": 0, \"atk\": 3, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(258,'水跃鱼',2500,'在水里时会用脸颊上的腮呼吸。如果遇到危险，会发挥出惊人的力量，能击碎比自己身体还大的岩石。',875,'水','',50,70,50,50,50,40,'173',0,10,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(259,'沼跃鱼',0,'能在烂泥中快速移动。这绝对比在水中游动要来的更快。腰腿很发达，可以用２条腿走路。',875,'水','地面',70,85,70,60,70,50,'0',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(260,'巨沼怪',0,'巨沼怪能通过用鳍感知波涛声和海风的细微变化来预测暴风雨。发生暴风雨时，会堆积岩石保护巢穴。',875,'水','地面',100,110,90,85,90,60,'',0,0,0,'{\"hp\": 0, \"atk\": 3, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(261,'土狼犬',5000,'性格执着的宝可梦。一旦盯上某个猎物，就会追到对方精疲力尽。',500,'恶','',35,55,35,30,30,35,'102,103,108,133,134',150,40,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(262,'大狼犬',0,'体内残留着群体行动的野性血液，只会认优秀的训练家为首领，并听从其命令。',500,'恶','',70,90,70,60,60,70,'149,150,154,157',150,40,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(263,'蛇纹熊',5000,'会用背上的硬毛摩擦树木，留下代表自己领地的标记。还会装死欺骗敌人。',500,'普通','',38,30,41,30,41,60,'102,105,106,133,146',190,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(264,'直冲熊',0,'看到猎物就会笔直地猛跑过去。虽然速度能超越１００公里的时速，但不急停的话，就无法转弯。',500,'普通','',78,70,61,50,61,100,'146,149,150,154',80,30,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(265,'刺尾虫',5000,'会把尾部的刺对准想捉自己当食物的大王燕进行抵抗。能用渗出的毒来削弱对方。',500,'虫','',45,45,35,20,30,20,'109',75,80,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(266,'甲壳茧',0,'虽然过去它被认为在进化之前会忍着什么都不吃，但实际上它好像会喝挂在丝线上的雨水解渴。',500,'虫','',50,35,55,25,25,15,'109',200,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(267,'狩猎凤蝶',0,'像针一样的长长嘴巴圆圆卷起，在采集花粉时非常方便。会随着春风四处采集花粉。',500,'虫','飞行',60,70,50,100,50,65,'',25,15,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 3, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(268,'盾甲茧',5000,'一旦动了就无法进化出强壮的身体，所以无论受到怎样的痛击都不会动。不过那时受到的疼痛它永远都不会忘记',500,'虫','',50,35,55,25,25,15,'109',200,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(269,'毒粉蛾',0,'扇动翅膀会扬起细小的剧毒粉末。一旦吸入就连职业摔角手也会卧病不起。会用像雷达一样的触角寻找食物。',500,'虫','毒',60,50,70,50,90,65,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,0,'[0, 0]',1),
(270,'莲叶童子',5000,'据说原本是生活在陆地上的，但因为头上的叶子变重了，所以变成了浮在水面上生活。',500,'水','草',40,30,30,40,50,30,'127',150,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(271,'莲帽小童',0,'全身覆盖着黏糊糊的粘液，如果被它的手摸到，就会感觉很恶心。经常被误认为是人类的孩子。',500,'水','草',60,50,50,60,70,50,'127',70,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(272,'乐天河童',0,'它有着听到欢快的节奏，身上的细胞就会活跃起来的体质。这让它在战斗时也能发挥出强大的力量。',500,'水','草',80,70,70,90,100,70,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 3, \"spd\": 0}',0,0,'[0, 0]',1),
(273,'橡实果',5000,'悬挂在树枝上的样子和树果一模一样。会突然动起来吓唬其他宝可梦。还会每天用叶子擦亮身体１次哦。',500,'草','',40,40,50,30,30,30,'103,143,149',200,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(274,'长鼻叶',0,'会拔下头上的叶子做成草笛。长鼻叶吹奏出的草笛声会让在森林里迷路的人感到不安。',500,'草','恶',70,70,40,60,40,60,'149,150',80,60,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(275,'狡猾天狗',0,'大大的团扇可以掀起风速３０米的强风吹跑一切。它是隐居在森林深处的宝可梦。',500,'草','恶',90,100,60,90,60,80,'',0,0,0,'{\"hp\": 0, \"atk\": 3, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(276,'傲骨燕',5000,'由于才刚刚离巢，所以到了晚上有时会因太寂寞而哭出来。以捕捉住在森林里的刺尾虫为食。',500,'普通','飞行',40,55,30,30,30,85,'108,131,134',150,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(277,'大王燕',0,'不会疏于修整自己那光鲜的羽毛。２只大王燕聚集在一起后，一定会把对方的羽毛修整得更漂亮。',500,'普通','飞行',60,85,60,75,50,125,'',33,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(278,'长翅鸥',5000,'会用长长的翅膀迎着海风，像滑翔机一样滑翔。休息的时候会收拢翅膀。',500,'水','飞行',40,30,30,55,30,85,'110,111,114,116,117,118,132,133,144,146,147,148,151,155,159,160,163,164,165,169,170,171,175,176,183',190,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(279,'大嘴鸥',0,'鸟嘴里放着小型宝可梦的飞天快递员。累了就会浮在海上休息。',500,'水','飞行',60,50,100,95,70,65,'110,111,114,116,117,132,133,142,144,147,148,150,151,155,159,160,163,164,165,169,170,171,175,176,183',100,20,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(280,'拉鲁拉丝',5000,'能用头上的角感知人的情绪。据说它会出现在心情愉快的人面前。',500,'超能','妖精',28,25,25,45,35,40,'103',40,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(281,'奇鲁莉安',0,'能够敏锐地感受到训练家的情绪。在心情好时它会翩翩起舞。',500,'超能','妖精',38,35,35,65,55,50,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(282,'沙奈朵',0,'它会拼命保护自己所信任的训练家。有着预知未来的能力。',500,'超能','妖精',68,65,65,125,115,80,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 3, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(283,'溜溜糖球',5000,'栖息在水草丛生的池塘或沼泽里。会经常和栖息地以及食物都与自己相近的滴蛛争斗。',500,'虫','水',40,30,32,50,52,65,'105',200,60,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(284,'雨翅蛾',0,'像薄薄的翅膀一样的触角很容易吸收湿气。雨天会静静地待在树洞等地方度过。',500,'虫','飞行',70,60,62,100,82,80,'133',100,30,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(285,'蘑蘑菇',5000,'感觉到了危险后，它就会摇动身体，从头顶上撒出能让草木都枯萎的剧毒孢子。',500,'草','',60,40,60,40,60,35,'109',180,60,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(286,'斗笠菇',0,'尾巴上的种子是由毒孢子变硬后形成的，所以吃下去的话可不得了。吃上一口肚子就会翻江倒海。',500,'草','格斗',60,130,80,60,60,70,'0',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(287,'懒人獭',0,'心脏每分钟只跳动１次。因为是不管怎样都会一直趴着的宝可梦，所以几乎不会看到它动的样子。',500,'普通','',60,60,60,35,35,30,'',0,0,0,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(288,'过动猿',0,'一刻也停不下来的宝可梦。就算想睡觉了，全身血液也还会沸腾，不去森林里到处奔跑就无法平息下来。',500,'普通','',80,80,80,55,55,90,'',45,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(289,'请假王',0,'刻在草原上半径１米的圆圈，是由请假王横躺着吃光了身边的草后所形成的。',500,'普通','',150,160,100,95,65,100,'',0,0,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(290,'土居忍士',5000,'会用锋利的爪子削开树木的根部，并吸取其中的水分和营养。不适应耀眼的阳光。',500,'虫','地面',31,45,90,30,30,40,'134',80,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(291,'铁面忍者',0,'如果没有好好培育，它就会不听话，会持续大叫，所以据说它是用来测试训练家本领的宝可梦。',500,'虫','飞行',61,90,45,50,50,160,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(292,'脱壳忍者',2500,'它是一种在土居忍士进化时，不知为何会擅自出现在精灵球里的宝可梦。身体完全不动，也不呼吸。',-1,'虫','幽灵',1,90,45,30,30,40,'172',0,5,1,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(293,'咕妞妞',5000,'一旦大叫起来，就会被自己的声音吓到，然后以更大的声音大吼大叫起来。停止大叫后就会累得睡着。',500,'普通','',64,51,23,51,23,28,'134,136',130,40,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(294,'吼爆弹',0,'会一边跺脚一边大叫。大叫后的一段时间内无法听到任何声音是其弱点。',500,'普通','',84,71,43,71,43,48,'126,135,157,179',45,30,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(295,'爆音怪',0,'会从身上的洞里传出笛声一样的声音，并以此来将向伙伴传递感情。只有在战斗时才会发出大叫声。',500,'普通','',104,91,63,91,73,68,'135,179',80,40,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(296,'幕下力士',5000,'据说为了培育强大的幕下力士，存在着一种训练家们按传统手法制作的火锅料理。',750,'格斗','',72,60,30,20,30,25,'113',80,40,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(297,'铁掌力士',0,'体型粗壮的铁掌力士未必强大。即便身型矮小，也有身轻如燕，擅长巧力的铁掌力士。',750,'格斗','',144,120,60,40,60,50,'126,179',20,20,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(298,'露力丽',5000,'尾巴里贮满了成长时所需的营养。会坐在充满弹性的尾巴上玩耍。',250,'普通','妖精',50,20,40,20,40,20,'',0,0,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(299,'朝北鼻',5000,'由于它的鼻子是由磁铁构成的，所以这种宝可梦一年到头脸都朝着北方。',500,'岩石','',30,45,135,45,90,30,'113',100,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(300,'向尾喵',5000,'会追着自己尾巴到处跑的宝可梦。野生的向尾喵生活在森林中的树洞里。有着可爱的脸蛋，作为宠物非常受欢迎。',250,'普通','',50,45,45,35,35,50,'134',45,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(301,'优雅猫',0,'过着居无定所生活的宝可梦。即使有其他宝可梦接近自己睡觉的地方，也绝不会去争斗，而会换个地方睡觉。',250,'普通','',70,65,65,55,55,90,'',0,0,0,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',0,0,'[0, 0]',1),
(302,'勾魂眼',5000,'所吃宝石的成分会在身体表面浮现出来。所形成的花纹变化无限。',500,'恶','幽灵',50,75,75,65,65,50,'113,172',30,50,1,'{\"hp\": 0, \"atk\": 1, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(303,'大嘴娃',5000,'拥有２张嘴。因为头部后面的大颚里没有味觉，所以那里用来吃不喜欢的东西。',500,'钢','妖精',50,85,85,55,55,50,'179',50,50,1,'{\"hp\": 0, \"atk\": 1, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(304,'可可多拉',8000,'如果用钢铁之躯全力撞击，就连翻斗车也能一次撞碎。会大口大口地将被撞坏的翻斗车吃掉。',500,'钢','岩石',50,70,100,40,40,30,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(305,'可多拉',0,'会吃石头或水中含有的铁质。在埋藏有铁矿石的山上筑巢，会和那些前来挖铁矿的人争斗。',500,'钢','岩石',60,90,140,50,50,40,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(306,'波士可多拉',0,'会用能够刺穿铁板的锐利尖角在撞击敌人的同时攻击对方。',500,'钢','岩石',70,110,180,60,60,50,'',0,50,0,'{\"hp\": 0, \"atk\": 0, \"def\": 3, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(307,'玛沙那',5000,'会通过冥想来提高精神能量。１天只吃１个树果。少吃也是修行的一个环节。',500,'格斗','超能',30,40,55,40,55,60,'179',120,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(308,'恰雷姆',0,'因瑜伽的力量第６感得到了提高，自己也变得可以操纵精神力量。会在１个月里不吃任何东西进行冥想。',500,'格斗','超能',60,60,75,60,75,80,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(309,'落雷兽',5000,'长长的体毛，通过摩擦在全身储存静电。是以速度为傲的宝可梦。',500,'电','',40,45,40,65,40,65,'118',50,60,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(310,'雷电兽',0,'用电刺激肌肉，所以能迅速行动。用电也能缓解肌肉疼痛，因此很快会治愈。',500,'电','',70,75,60,105,60,105,'145',20,30,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(311,'正电拍拍',5000,'给伙伴加油的时候，会从全身发出电火花并噼里啪啦地发光。如果伙伴输了，就会放声大哭。',500,'电','',60,50,40,85,75,95,'191',0,5,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(312,'负电拍拍',5000,'非常喜欢给伙伴加油的宝可梦。如果伙伴快要输掉的话，体内迸发出的火花数量就会不断增多哦。',500,'电','',60,40,50,75,85,95,'191',0,5,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(313,'电萤虫',5000,'会利用尾巴的亮光，成群结队地在夜空中描绘几何图形。非常喜欢甜甜萤放出的甜甜香气。',1000,'虫','',65,73,75,47,85,85,'143',35,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(314,'甜甜萤',5000,'会诱导电萤虫描绘记号。据说记号描绘得越复杂的甜甜萤，就会越受到伙伴的尊敬哦。',0,'虫','',65,47,75,73,85,85,'143',35,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(315,'毒蔷薇',5000,'据说有极个别的毒蔷薇会开出色彩罕见的花朵。头上的刺带有剧毒。',500,'草','毒',50,60,45,100,80,65,'143',40,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(316,'溶食兽',5000,'身体的大部分都是胃，心脏和大脑非常小。有着能溶化任何东西的特殊胃液。',500,'毒','',70,43,53,43,53,40,'118',200,50,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(317,'吞食兽',0,'嘴里１颗牙齿都没有，所以会吞食任何东西。嘴巴完全张开的时候非常大，可以将汽车轮胎整个塞进去。',500,'毒','',100,73,83,73,83,55,'',0,0,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(318,'利牙鱼',5000,'结实的颚部和牙齿，如果是木头造的船，轻易就可以咬碎。围绕食物的问题，和野蛮鲈鱼争斗。',500,'水','恶',45,90,20,65,20,65,'144,158,160',45,40,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(319,'巨牙鲨',0,'会从臀部的孔里喷出喝入的海水来游泳。对血的气味十分敏感。',500,'水','恶',70,120,40,95,40,95,'158,159,160,163,164',30,20,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(320,'吼吼鲸',5000,'在极其偶然的情况下它们会群体冲上沙滩，据说这是源自它们远古时代居住在陆地时的习性。',500,'水','',130,70,35,70,35,60,'110,111,114,116,117,118,119,128,130,132,142,144,146,159,160,163,164,165,178',45,40,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(321,'吼鲸王',0,'小小的吼吼鲸如果被巨牙鲨和破破舵轮袭击的话，群体伙伴就会团结一致来守护。',500,'水','',170,90,45,90,45,60,'162',20,20,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(322,'呆火驼',5000,'体内储存了１２００度的熔岩。一旦被水淋湿，熔岩就会冷凝、变重。动作也会因此变得迟缓。',500,'火','地面',60,60,40,65,45,35,'121,139',120,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(323,'喷火驼',0,'背上的驼峰是由骨头演变而来的。时不时会喷出沸腾的熔岩。愤怒时好像会经常喷发。',500,'火','地面',70,100,70,105,75,40,'157',20,20,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(324,'煤炭龟',5000,'燃烧煤炭，制作能量。如果煤炭烧尽，身体就会变得无法动弹。',500,'火','',70,85,140,85,70,20,'122',120,60,1,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(325,'跳跳猪',5000,'会用尾巴代替弹簧，一直在跳来跳去。靠跳跃时的震动来使心脏跳动。',500,'超能','',60,25,35,70,80,60,'138,139',60,70,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(326,'噗噗猪',0,'能用黑珍珠增强自己的精神力量。会用神奇的舞步操纵对手的心。',500,'超能','',80,45,65,90,110,80,'138',50,30,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(327,'晃晃斑',5000,'每一只身上的斑点花纹都不同。会用晃晃悠悠的动作绝妙地躲避对手的攻击。',500,'普通','',60,60,60,60,60,60,'123',45,65,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(328,'大颚蚁',5000,'制造兼有陷阱功能的巢穴，一心一意埋伏着等待猎物。到了晚上就潜回沙中睡觉。',500,'地面','',45,100,45,45,45,10,'141',120,50,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(329,'超音波幼虫',0,'会振动翅膀，产生特殊的音波。呆在一起的训练家有必要准备好耳塞。',500,'地面','龙',50,70,50,50,50,70,'141',50,10,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',0,0,'[0, 0]',1),
(330,'沙漠蜻蜓',0,'由于会被美丽歌声般的振翅声夺走心神，因此沙漠中不断有人遇难。',500,'地面','龙',80,100,80,80,80,100,'141',30,10,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(331,'刺球仙人掌',5000,'越是在少雨严酷的环境中，就越是会绽放出美丽且香味浓郁的花朵。会挥舞带刺的手臂战斗。',500,'草','',50,85,40,85,40,35,'139,141',200,70,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(332,'梦歌仙人掌',0,'深夜会成群结队紧紧跟在行走在沙漠上的旅行者身后。会一直等到他累得无法动弹为止。',500,'草','恶',70,115,60,115,60,55,'141',30,20,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(333,'青绵鸟',5000,'看到脏东西就会用棉花一样的翅膀不停地擦拭，是爱干净的宝可梦。翅膀脏了的话就会去河里冲洗干净。',500,'普通','飞行',45,40,60,40,75,50,'127,131',155,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(334,'七夕青鸟',0,'会用优美的高音歌唱的宝可梦。能用棉花云一样的翅膀借助上升气流飞向高空。',500,'龙','飞行',75,70,90,70,105,80,'126,127,131,135,138,157,172,179',45,10,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(335,'猫鼬斩',5000,'平常用４只脚行动，但是愤怒时会用后脚站立并伸出前脚的爪子。从祖辈那时开始，饭匙蛇就是它的劲敌。',500,'普通','',73,115,60,60,60,90,'127',40,45,1,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(336,'饭匙蛇',5000,'在用如刀刃般的尾巴切开敌人的同时，会将渗出的剧毒撒向对方。一直在和宿敌猫鼬斩战斗。',500,'毒','',73,100,60,100,60,65,'127',45,40,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(337,'月石',5000,'有着会在满月期间变得活跃起来的习性。会飘浮在空中移动，红色的眼睛充满魄力，能让看到它的对方心生恐惧。',-1,'岩石','超能',90,55,65,95,85,70,'130,185',0,50,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(338,'太阳岩',5000,'太阳光线是其力量之源。据说可以读取对方的心声。会通过旋转身体放出高热。',-1,'岩石','超能',90,95,85,55,65,70,'130,185',20,50,1,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(339,'泥泥鳅',5000,'胡子上布满神经。能像人类的鼻子和舌头那样感知气味和味道。',500,'水','地面',50,48,43,46,41,60,'115,120,128,148',200,40,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(340,'鲶鱼王',0,'它的视力不太好。会通过胡子来感知水的振动，掌握猎物的位置。',500,'水','地面',110,78,73,76,71,60,'158,162,163,164,165,166',45,50,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(341,'龙虾小兵',5000,'对环境的适应力非常强。呆在浑浊臭水沟里的大概就是丑丑鱼和这家伙。',500,'水','',43,80,65,50,35,35,'104,107,115,143,158',150,40,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(342,'铁螯龙虾',0,'钳子经常会掉。钳子里面跟好胜蟹和铁臂枪虾不同，有臭泥味，实在很难吃。',500,'水','恶',63,120,85,90,55,55,'158',45,50,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(343,'天秤偶',5000,'如果发现了伙伴，就会吵吵闹闹地叫唤着聚集。会大量出现在古代的墓地里。',-1,'地面','超能',40,40,55,40,70,55,'141',150,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(344,'念力土偶',0,'好像是古代人模仿从天而降的某物制作而成。会从双臂发射出光束。',-1,'地面','超能',60,70,105,70,120,75,'172',20,20,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(345,'触手百合',5000,'用强力的吸盘扒在岩石上，因此无论怎样的惊涛骇浪也不会被冲走。',875,'岩石','草',66,41,77,61,87,23,'125',0,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(346,'摇篮百合',0,'古代海里的食肉宝可梦。能用８根触手捕捉猎物，一边用消化液溶化一边吃。',875,'岩石','草',86,81,97,81,107,43,'125',0,40,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(347,'太古羽虫',5000,'古代虫宝可梦中的一种。好像会使用８根翅膀游泳，速度意外的快。',875,'岩石','虫',45,95,50,40,50,75,'125',0,40,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(348,'太古盔甲',0,'从海里变成了在陆地生活。据了解，是一部分虫宝可梦的祖先。',875,'岩石','虫',75,125,100,70,80,45,'125',0,50,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(349,'丑丑鱼',5000,'因为长得寒碜，大多数人看都不看，但是有只收集丑丑鱼的收藏家。',500,'水',' ',20,15,20,10,55,80,'',0,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(350,'美纳斯',0,'栖息在很大的湖底。听说，只要看见它那美丽的样子，心里的污秽就会被清除。',500,'水','',95,60,79,100,125,81,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(351,'飘浮泡泡',5000,'样子会根据天气发生变化。天气越恶劣，性格也会变得越暴躁。',500,'普通','',70,70,70,70,70,70,'191,193',0,5,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(352,'变隐龙',0,'在不隐身的时候，身体的颜色也会随着心情和状态改变。颜色越浓的时候越有精神。',500,'普通','',60,90,70,60,120,40,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(353,'怨影娃娃',5000,'非常喜欢怨恨的感情。会成排地悬挂在心怀怨恨的人的屋檐下。',500,'幽灵','',44,75,35,63,33,45,'150,154',80,30,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(354,'诅咒娃娃',0,'怨念附在被丢弃的玩偶身上，变成了宝可梦。会一直寻找丢弃自己的孩子。',500,'幽灵','',64,115,65,83,63,65,'172',20,10,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(355,'夜巡灵',5000,'会无止境地追逐猎物。性格十分执着，但是太阳升起后就会放弃。',500,'幽灵','',20,40,90,30,90,25,'152,153',50,30,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',1,0,'[0, 0]',1),
(356,'彷徨夜灵',0,'身体内部是空洞，据说会把窥视自己的对手吸进去。',500,'幽灵','',40,70,130,60,130,25,'172',20,10,0,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(357,'热带龙',5000,'脖子上的那串水果很美味，很受欢迎。在温暖的地方，有许多培育热带龙的牧场。',500,'草','飞行',99,68,83,72,87,51,'146',25,40,1,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(358,'风铃铃',5000,'拥有超音波的叫声。轻飘飘地浮起来，乘着风去远方旅行。',500,'超能','',75,50,80,95,90,65,'152,153',100,20,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(359,'阿勃梭鲁',5000,'老人们称之为灾祸宝可梦，对它很忌惮。但人们对它预知灾害的能力非常感兴趣。',500,'恶','',65,130,60,75,60,75,'',0,0,1,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(360,'小果然',5000,'通过与伙伴们进行互推游戏，练就了很强的忍耐力。非常喜欢吃甘甜的水果。',500,'超能','',95,23,48,23,48,23,'173',0,20,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(361,'雪童子',5000,'寒冷地方的富人们，好像都会有小时候和雪童子一起玩的回忆。',500,'冰','',50,50,50,50,50,50,'181',65,40,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(362,'冰鬼护',0,'不那么坚硬的岩石是它的本体。能够冻住空气中的水分，将冰之装甲裹在身上。',500,'冰','',80,80,80,80,80,80,'',0,0,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(363,'海豹球',5000,'该宝可梦总是翻滚着移动。在有浮冰的季节，可以看到它在冰上翻滚着渡海的样子。',500,'冰','水',70,40,50,55,50,25,'181',35,30,1,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(364,'海魔狮',0,'总是在用鼻子转着什么。一边转一边确认气味和触感，分辨喜欢的和讨厌的东西。',500,'冰','水',90,60,70,75,70,45,'',0,0,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(365,'帝牙海狮',0,'一边用巨大的獠牙咬碎冰山，一边在冰点下的海里游来游去。丰厚的脂肪可以反弹攻击。',500,'冰','水',110,80,90,95,90,65,'158,162,166',10,10,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(366,'珍珠贝',5000,'珍珠贝的珍珠非常贵重。据说，其价值或许是大舌贝珍珠的１０倍以上。',500,'水','',35,64,85,74,55,32,'166',80,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(367,'猎斑鱼',0,'栖息在深海中。传说，如果猎斑鱼被冲上沙滩，就会有不祥的事情发生。',500,'水','',55,104,105,94,75,52,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(368,'樱花鱼',0,'吸食猎物的体液。剩下的肉会沉入海底，成为其他宝可梦的食物。',500,'水','',55,84,105,114,75,52,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(369,'古空棘鱼',5000,'好像作为生命已是完成状态，所以在１亿年间，样子完全没有变化。',875,'水','岩石',100,90,130,45,65,55,'162,166',200,80,1,'{\"hp\": 1, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
(370,'爱心鱼',5000,'温暖海域的珊瑚礁是它的栖息地。特别喜欢在太阳珊瑚的枝条间睡觉。',250,'水','',43,30,55,40,65,97,'165,178',40,40,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',1,0,'[0, 0]',1),
(371,'宝贝龙',10000,'也有说法，说它通过重重地敲打脑袋来刺激影响进化的细胞。',500,'龙','',45,75,60,40,30,50,'',10,10,1,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',1,0,'[0, 0]',1),
