(575,'哥德小童',0,'据说会在星光闪耀的夜晚把睡着的孩子们带走。也有人称它为惩罚魔女。',250,'超能','',60,45,70,75,85,55,'',100,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
