(577,'单卵细胞球',5000,'身体被特殊的液体包裹着，许多人因此认为它即使在宇宙中也能存活。',500,'超能','',45,30,40,105,50,20,'',200,0,1,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
