(728,'球球海狮',0,'球球海獅，海獅寶可夢，牠會操縱水做的氣球。為了吹出大大的氣球，還會勤奮地反覆練習。',875,'水','',50,54,54,66,56,40,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 1, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(729,'花漾海狮',0,'花漾海獅，偶像寶可夢，水屬性。能吹出五顏六色的多彩氣球，在月亮高掛的夜晚，還會跟同伴一起跳舞。',875,'水','',60,69,69,91,81,50,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(730,'西狮海壬',0,'憑著那動人的姿態，西狮海壬被冠以歌姬的美譽。反射了月光後閃閃發光的氣球，像幻想的舞台般優美。',875,'水','妖精',80,74,74,126,116,60,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 3, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(731,'小笃儿',0,'啄木鳥寶可夢，以每秒16次的速度啄出樹洞，並且把食物儲藏在樹洞裡。',500,'普通','飞行',35,75,30,30,30,65,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(732,'喇叭啄鸟',0,'喇叭啄鳥，喇叭喙寶可夢，是小篤鳥的進化形。能一口氣朝敵人或獵物射出儲存在嘴巴裡面的樹果種子。',500,'普通','飞行',55,85,50,40,50,75,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(733,'铳嘴大鸟',0,'銃嘴大鳥，銃炮寶可夢，是喇叭啄鳥的進化形。加熱後的鳥嘴溫度可以超過一百度，如果被啄到就會嚴重燙傷。',500,'普通','飞行',80,120,75,75,75,60,'',0,0,0,'{\"hp\": 0, \"atk\": 3, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(734,'猫鼬少',0,'貓鼬少，巡迴寶可夢。具有強壯的牙齒跟下顎，進化成貓鼬探長之後，就會變得更執著，而且更有忍耐力。',500,'普通','',48,70,30,30,30,45,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(735,'猫鼬探长',0,'找到猎物的踪迹后，就会坚持蹲守在那个地方，但到了傍晚就会昏昏欲睡。',500,'普通','',88,110,60,55,60,45,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(736,'强颚鸡母虫',0,'会用巨大的颚部在森林中挖地制造巢穴。最喜欢甜甜的树汁。',500,'虫','',47,62,45,55,45,46,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(737,'虫电宝',0,'用结实的外壳保护自己。会从颚部的尖端放出电流反击对手。',500,'虫','电',57,82,95,55,75,36,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(738,'锹农炮虫',0,'用腹部发电，并把电力集中至大大的颚部，释放出能量惊人的光束。',500,'虫','电',77,70,90,145,75,43,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 3, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(739,'好胜蟹',0,'因为打架太频繁，钳子常常掉落，但很快又会长出来。钳子里的肉很少，但味道浓郁非常鲜美。',500,'格斗','',47,82,57,42,47,63,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(740,'好胜毛蟹',0,'应该是以登顶为目标的，却阴差阳错地登上了雪山，在忍耐寒冷的过程中，由于毛发不断生长而进化成这样。',500,'格斗','冰',97,132,77,62,67,43,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(741,'花舞鸟',0,'用热情的舞蹈抓住敌人的心，趁对方疏忽的间隙，用熊熊燃烧的火焰将其烧尽。',250,'火','飞行',75,70,70,98,70,93,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(742,'萌虻',0,'喜欢吃花蜜和花粉。会在花圃里寻找食物，和巴大蝶展开小冲突。',500,'虫','妖精',40,45,40,55,40,84,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',0,0,'[0, 0]',1),
(743,'蝶结萌虻',0,'能够从湿度和风向预测天气状况。只有在持续晴天的时候才能看见它的样子。',500,'虫','妖精',60,55,60,95,70,124,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(744,'岩狗狗',0,'从一开始就一直和人类生活。当训练家悲伤的时候，它会察觉到，不会离开对方的身边。',500,'岩石','',45,65,40,30,40,60,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(745,'鬃岩狼人',0,'面对的的敌人越强，内心就越兴奋。所使出的一击必杀的头锤甚至能把大石头都撞得粉碎。',500,'岩石','',75,115,65,55,65,112,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(746,'弱丁鱼',0,'虽然单独１只十分弱小，只要大家聚在一起齐心协力，就能拥有堪称海之魔物的力量。',500,'水','',45,20,20,25,25,40,'',0,0,0,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(747,'好坏星',0,'在海底和海岸爬来爬去。生长在太阳珊瑚头上的珊瑚是它非常喜欢吃的东西。',500,'毒','水',50,53,62,43,52,45,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(748,'超坏星',0,'超坏星看起来像是一顶布满尖刺的圆顶帐篷，这实际上是它在用触腕保护自己的姿态。',500,'毒','水',50,63,152,53,142,35,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(749,'泥驴仔',0,'非常喜欢玩泥巴。如果不每天在泥巴里玩的话，就会因压力而不听话。',500,'地面','',70,100,70,45,55,45,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(750,'重泥挽马',0,'它拿手的攻击方式是用沾满了泥的沉重的脚踢对手。即使是大型卡车也能轻松踢成废铁。',500,'地面','',100,125,100,55,85,35,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(751,'滴蛛',0,'如果滴蛛同类之间相遇，它们会自豪地用头上的水泡炫耀。水泡小的一方就会让路。',500,'水','虫',38,40,52,40,72,27,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(752,'滴蛛霸',0,'与外表不同，非常体贴。发现弱小的伙伴后，会让对方进入水泡，保护它。',500,'水','虫',68,70,92,50,132,42,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(753,'伪螳草',0,'太阳升起后，就会展开４片叶子进行日光浴。会从头顶发出好闻的味道哦。',500,'草','',40,55,35,50,35,35,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(754,'兰螳花',0,'像跳舞一样将敌人劈开。因优雅的姿态理所当然地被称为最艳丽的草属性宝可梦。',500,'草','',70,105,90,80,90,45,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(755,'睡睡菇',0,'喜欢阴暗潮湿的地方。到了夜里，蘑菇伞下储满的孢子就会发光。',500,'草','妖精',40,35,55,65,75,15,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(756,'灯罩夜菇',0,'深夜前往灯罩夜菇栖息的森林是很危险的。会被怪异的光线诱惑，再也回不来了。',500,'草','妖精',60,45,80,90,100,30,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(757,'夜盗火蜥',0,'栖息在火山和干燥的岩石地带。放出有甜甜香味的毒瓦斯，把虫宝可梦吸引过来再袭击。',875,'毒','火',48,44,40,71,40,77,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',0,0,'[0, 0]',1),
(758,'焰后蜥',0,'毒瓦斯中含有很多的费洛蒙。稀释以后可以制作成性感的香水。',0,'毒','火',68,64,60,111,60,117,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(759,'童偶熊',0,'如果被亲密的对象和伙伴以外的接触到，就会用可怕的力量发狂，所以很危险。',500,'普通','格斗',70,75,50,45,50,50,'',0,0,0,'{\"hp\": 0, \"atk\": 1, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(760,'穿着熊',0,'如果它认定你是它的伙伴，便会要来拥抱你来表示喜爱。但这会弄碎你的骨头，非常危险。',500,'普通','格斗',120,125,80,55,60,60,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(761,'甜竹竹',0,'因为闻起来又甜又香的气味而被鸟宝可梦袭击，但是不太聪明，所以根本没在意。',0,'草','',42,30,38,30,38,32,'',0,0,0,'{\"hp\": 1, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(762,'甜舞妮',0,'总是精神饱满地跳来跳去。因为有着充满活力的样子和好闻的香味，宝可梦都会聚集到它周围来。',0,'草','',52,40,48,40,48,62,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 2}',0,0,'[0, 0]',1),
(763,'甜冷美后',0,'擅长运用自己的脚来踢。用脚踩住已被打倒的对手，大笑着炫耀自己的胜利。',0,'草','',72,120,98,50,98,72,'',0,0,0,'{\"hp\": 0, \"atk\": 3, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(764,'花疗环环',0,'从头上伸出有粘性的藤蔓，用摘下的花朵装饰自己。没有花就会感到不安。',250,'妖精','',51,52,90,82,110,100,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(765,'智挥猩',0,'栖息在丛林深处的树上。偶尔出现在海边，与呆呆王较量谁更聪明。',500,'普通','超能',90,60,80,90,110,60,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(766,'投掷猴',0,'树果是它的武器，也是主食。在群体中，能把树果投得最远的就是它们的老大。',500,'格斗','',100,120,90,40,60,80,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(767,'胆小虫',0,'无论是腐烂的东西还是垃圾，胆小虫都会吃得一干二净，是大自然的清道夫。',500,'虫','水',25,35,40,20,30,80,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 1}',0,0,'[0, 0]',1),
(768,'具甲武者',0,'具甲武者为了胜利会不择手段。牠平常就在巢穴里好像冥想一般静静地生活，有时也会带领着胆小虫。',500,'虫','水',75,125,140,60,90,40,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(769,'沙丘娃',0,'玩沙子时堆成的沙山，如果没有在回家时破坏掉，就有可能会被魂魄附着，成为沙丘娃。',500,'幽灵','地面',55,55,80,70,45,15,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(770,'噬沙堡爷',0,'操纵人们，让沙丘进化为沙堡。诅咒的力量也得到了提升。',500,'幽灵','地面',85,75,110,100,75,35,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(771,'拳海参',0,'栖息在沙滩等浅海地区。从身体里飞出体内器官，捕捉食物，或是与敌人战斗。',500,'水','',55,60,130,30,130,5,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(772,'属性：空',0,'是为了某个任务而被开发出来的宝可梦武器。因为在试验中暴走而被冻结了。',-1,'普通','',95,95,95,95,95,59,'',0,0,0,'{\"hp\": 2, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,1,'[0, 0]',1),
(773,'银伴战兽',0,'因为与同伴之间的信赖而觉醒。发挥自由变换属性的能力进行战斗。',-1,'普通','',95,95,95,95,95,95,'',0,0,0,'{\"hp\": 3, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,1,'[0, 0]',1),
(774,'小陨星',0,'原本栖息在臭氧层，身体的外壳变重后，就会向着地面落下。',-1,'岩石','飞行',60,60,100,60,100,60,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 1, \"spd\": 0}',0,0,'[0, 0]',1),
(775,'树枕尾熊',0,'出生后就一直都睡着。进入深度睡眠的时候，会变的一动也不动。',500,'普通','',65,115,65,75,95,65,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(776,'爆焰龟兽',0,'栖息在火山，吃硫磺和矿物。所吃食物的成分会成为爆炸的甲壳的来源。',500,'火','龙',60,78,135,91,85,36,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(777,'托戈德玛尔',0,'背上的长毛是引雷针。引来打下的雷，沐浴雷电后，就会将之储存在电力袋中。',500,'电','钢',65,98,63,40,73,96,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(778,'谜拟Ｑ',0,'为了让别人不要害怕自己，特意穿上了看似皮卡丘的破布，结果却变得更加令人毛骨悚然。',500,'幽灵','妖精',55,90,80,50,105,96,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 0, \"spdef\": 2, \"spd\": 0}',0,0,'[0, 0]',1),
(779,'磨牙彩皮鱼',0,'厚实的皮肤连好坏星的针也穿不透。会用结实的牙齿嘎嘣嘎嘣地咬碎针吃下去。',500,'水','超能',68,105,70,70,70,92,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(780,'老翁龙',0,'心地善良爱亲近人，但只要生气就会刮起强风吹倒一切。',500,'普通','龙',78,60,85,135,91,36,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 0, \"spatk\": 2, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(781,'破破舵轮',0,'像锁链一样的绿色碎藻能绵延数百米。不知为何与垃垃藻关系很好。',-1,'幽灵','草',70,131,100,86,90,40,'',0,0,0,'{\"hp\": 0, \"atk\": 2, \"def\": 0, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(782,'心鳞宝',0,'用头部的鳞片砰砰砰地敲响岩石和地面，威吓对手。也会用声音和伙伴联络。',500,'龙','',45,55,65,45,45,45,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 1, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
(783,'鳞甲龙',0,'鳞片会不断更替。随着每次崭新蜕变，鳞片会变得坚硬又锋利。',500,'龙','格斗',55,75,90,65,70,65,'',0,0,0,'{\"hp\": 0, \"atk\": 0, \"def\": 2, \"spatk\": 0, \"spdef\": 0, \"spd\": 0}',0,0,'[0, 0]',1),
